from psyclone.transformations import (
    Dynamo0p3RedundantComputationTrans,
    Dynamo0p3AsyncHaloExchangeTrans,
    OMPLoopTrans,
    OMPColourTrans,
    IntrinsicInlineTrans,
    TransformationError
)
from psyclone.core import get_constants

# Boolean variables to control transformations
APPLY_REDUNDANT_COMPUTATION = True
APPLY_ASYNC_HALO_EXCHANGE = True
APPLY_OPENMP_COLOURING = True
APPLY_INTRINSIC_INLINING = True

def apply_transformations(psy):
    """
    Applies a series of transformations to the given 'psy' object.
    Transformations include redundant computation, asynchronous halo exchanges,
    OpenMP colouring, and intrinsic inlining, controlled by boolean variables.
    Handles TransformationErrors and returns the transformed 'psy' object.
    """
    rc_trans = Dynamo0p3RedundantComputationTrans()
    async_halo_trans = Dynamo0p3AsyncHaloExchangeTrans()
    omp_colour_trans = OMPColourTrans()
    omp_loop_trans = OMPLoopTrans()
    intrinsic_inline_trans = IntrinsicInlineTrans()

    for invoke in psy.invokes.invoke_list:
        schedule = invoke.schedule
        try:
            if APPLY_REDUNDANT_COMPUTATION:
                for loop in schedule.loops():
                    rc_trans.apply(loop)
            if APPLY_ASYNC_HALO_EXCHANGE:
                for node in schedule.walk(schedule.halo_exchange_class):
                    async_halo_trans.apply(node)
            if APPLY_OPENMP_COLOURING:
                for loop in schedule.loops():
                    if loop.loop_type == "colours":
                        omp_colour_trans.apply(loop)
                    else:
                        omp_loop_trans.apply(loop)
            if APPLY_INTRINSIC_INLINING:
                for intrinsic_call in schedule.walk(schedule.intrinsic_call_class):
                    intrinsic_inline_trans.apply(intrinsic_call)
        except TransformationError as err:
            print(f"TransformationError in invoke '{invoke.name}': {err}")
    return psy
